(()=>{
  "use strict";
  const esc=value=>String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]));
  const MODULES=[
    {id:"microscope",item:"",icon:"◉",title:"Microscopic World",image:"assets/microscopic-world-v1.png",kicker:"CORE LAB SYSTEM · ALWAYS AVAILABLE",summary:"Magnify bacteria, fungi and microscopic partners that are too small to see with the unaided eye.",effect:"micro",captions:["A microscope enlarges structures that are normally invisible.","Shape, movement and surroundings provide evidence for identification.","Some microorganisms help ecosystems; others can cause disease."]},
    {id:"dam",item:"dam-field-model",icon:"≈",title:"Beaver Dam Hydrology",image:"assets/science-beaver-wetland-v2.png",kicker:"BEAVER DAM FIELD MODEL",summary:"Compare fast stream water with the slower pond formed behind a dam.",effect:"dam",captions:["Branches, stones and mud form a barrier across moving water.","The current slows and deeper water gathers behind the barrier.","A new pond creates shelter for wetland organisms."]},
    {id:"pollination",item:"pollinator-lens",icon:"✣",title:"Pollination Transfer",image:"assets/science-bee-orchard-pollination-v1.png",kicker:"POLLINATOR OBSERVATION LENS",summary:"Track pollen as a bee travels between flowers.",effect:"pollen",captions:["A bee visits a flower to collect nectar and pollen.","Pollen grains attach to hairs on the bee's body.","A later flower receives pollen, helping seeds and fruit begin to form."]},
    {id:"wetland",item:"wetland-filter",icon:"≋",title:"Wetland Water Filter",image:"assets/science-wetland-effects-v2.png",kicker:"WETLAND WATER FILTER",summary:"Watch flowing water slow while suspended soil settles and roots protect the bank.",effect:"wetland",captions:["Wetland plants slow water moving through stems and roots.","When water slows, some suspended particles settle as silt.","Plant roots hold soil and can reduce erosion along the bank."]},
    {id:"foodweb",item:"pond-web-projector",icon:"⌬",title:"Pond Food Web",image:"assets/science-pond-food-web-v1.png",kicker:"POND FOOD-WEB PROJECTOR",summary:"Follow energy through several connected feeding paths in one pond.",effect:"web",captions:["Producers capture light energy and make food.","Arrows point from food toward the organism receiving the energy.","Changing one population can affect several connected populations."]},
    {id:"soil",item:"living-soil-core",icon:"⌁",title:"Living Soil Scanner",image:"assets/science-soil-ecosystem-v1.png",kicker:"LIVING SOIL RESEARCH CORE",summary:"Scan roots, air spaces, moisture, decomposers and earthworm tunnels below ground.",effect:"soil",captions:["Soil contains mineral particles, water, air and organic matter.","Earthworm tunnels help air and water move through the ground.","Decomposers recycle dead material into nutrients used by plants."]},
    {id:"seed",item:"orbital-seed-vault",icon:"✦",title:"Seed & Germination Archive",image:"assets/science-fruit-week-review-v2.png",kicker:"ORBITAL SEED VAULT",summary:"Compare seed structures, dispersal routes and the conditions needed for germination.",effect:"seed",captions:["A seed protects a plant embryo and often contains stored food.","Water and a suitable temperature can begin germination.","Roots grow downward while the shoot reaches toward light."]}
  ];
  let active=null,clipTimer=0,captionIndex=0;
  function ownedSet(state){return new Set(state.gemWorkshop?.owned||[])}
  function unlocked(module,owned){return!module.item||owned.has(module.item)}
  function overlay(effect){return`<div class="lab-animation lab-animation-${effect}" aria-hidden="true">${Array.from({length:8},(_,i)=>`<i style="--i:${i};--x:${10+(i%4)*24}%;--y:${18+Math.floor(i/4)*48}%;--r:${-24+i*7}deg;--d:${4.8+i*.35}s;--delay:${i*.3}s"></i>`).join("")}<span></span><b></b><em></em></div>`}
  function projection(module,playing=true){return`<section class="lab-projection ${playing?"playing":"paused"}" data-lab-effect="${module.effect}"><div class="lab-projector-frame"><img src="${esc(module.image)}" alt="${esc(module.title)} animated science projection">${overlay(module.effect)}<div class="lab-scanline"></div><span class="lab-video-badge">HOLOGRAM CLIP · 12 SEC LOOP</span></div><div class="lab-projection-copy"><small>${esc(module.kicker)}</small><h2>${esc(module.title)}</h2><p>${esc(module.summary)}</p><div class="lab-caption"><i></i><span id="labClipCaption">${esc(module.captions[captionIndex%module.captions.length])}</span></div><div class="lab-video-controls"><button id="labPlayPause">${playing?"Ⅱ Pause":"▶ Play"}</button><button id="labReplay">↻ Replay</button><span><i></i></span></div></div></section>`}
  function deviceCard(module,owned){const ready=unlocked(module,owned);return`<button class="lab-device ${ready?"ready":"locked"}" data-lab-module="${module.id}" ${ready?"":"aria-disabled='true'"}><i>${module.icon}</i><span><small>${ready?module.id==="microscope"?"CORE SYSTEM":"DEVICE INSTALLED":"GEM EXCHANGE REQUIRED"}</small><strong>${esc(module.title)}</strong><em>${ready?"Open hologram clip →":"Locked in Storage → Gem Workshop"}</em></span></button>`}
  function queueMarkup(state){const cards=(state.researchCards||[]).filter(card=>card.rarity&&card.rarity!=="common");return cards.length?cards.slice(-5).map(card=>`<article><img src="${esc(card.image)}" alt="${esc(card.name)} specimen card"><span><small>${esc(card.rarity.toUpperCase())} · ANALYSIS QUEUE</small><b>${esc(card.name)}</b><em>Safe in containment · select a compatible study protocol before release.</em></span></article>`).join(""):`<div class="lab-empty-queue"><b>NO RARE SPECIMENS WAITING</b><span>Rare and synthesized cards earned from Science chapters will appear here.</span></div>`}
  function render(context){
    active=context;clearInterval(clipTimer);captionIndex=0;
    const {root,state}=context,owned=ownedSet(state),selected=MODULES.find(module=>module.id===state.science.labSelected&&unlocked(module,owned))||MODULES[0],installed=MODULES.filter(module=>unlocked(module,owned)).length-1,synthesisReady=owned.has("living-soil-core")&&owned.has("orbital-seed-vault");
    state.science.labSelected=selected.id;context.save();root.scrollTop=0;
    root.innerHTML=`<section class="science-room-screen"><img class="science-room-bg" src="assets/science-earth-lab-v1.png" alt="Modern orbital Science Lab with holographic research stations"><div class="science-room-shade" aria-hidden="true"></div><header class="lab-header"><button id="labBack">← Cockpit</button><div><p>SCIENCE LAB · RESEARCH DECK</p><h1>Observe the invisible</h1><span>Study evidence first. Gem devices add new ways to investigate the same Science lessons.</span></div><aside><small>INSTALLED DEVICES</small><b>${installed}/6</b><span>${(state.researchCards||[]).filter(card=>card.rarity!=="common").length} specimens in queue</span></aside></header><main class="lab-workspace"><section class="lab-theater"><div class="lab-section-title"><div><small>HOLOGRAM RESEARCH THEATER</small><h2>Animated lesson models</h2></div><span>These are lightweight in-game clips, not prerecorded video files.</span></div><div id="labProjectionHost">${projection(selected,true)}</div></section><aside class="lab-equipment"><div class="lab-section-title"><div><small>DEVICE RACK</small><h2>Research tools</h2></div><button id="labGemWorkshop">Gem Workshop →</button></div><div class="lab-device-list">${MODULES.map(module=>deviceCard(module,owned)).join("")}</div></aside></main><section class="lab-lower-deck"><article class="lab-bay microscope-bay"><span>◉</span><div><small>MICROSCOPE BAY · OPEN</small><h3>Microscopic World</h3><p>Compare useful bacteria, fungi, cells and tiny ecosystem partners. This base station is always available.</p><button data-open-core="microscope">Start microscope scan →</button></div></article><article class="lab-bay synthesis-bay ${synthesisReady?"ready":"locked"}"><span>⬡</span><div><small>SEED & LIFE SYNTHESIS · ${synthesisReady?"READY":"BLOCKED"}</small><h3>Synthesis Chamber</h3><p>${synthesisReady?"Living Soil Core and Seed Vault are installed. The chamber can now compare traits and plan safe research recipes.":"Install both the Living Soil Research Core and Orbital Seed Vault. No creature or seed is consumed while this system is being developed."}</p><button id="labSynthesis" ${synthesisReady?"":"disabled"}>${synthesisReady?"Open synthesis planner →":"Need 2 research devices"}</button></div></article><article class="lab-queue"><div class="lab-section-title"><div><small>CONTAINMENT ARCHIVE</small><h2>Rare specimen queue</h2></div><span>Research before habitat release</span></div>${queueMarkup(state)}</article></section><div class="lab-notice" id="labNotice" hidden></div><div class="lab-modal-layer" id="labModal" hidden></div></section>`;
    bind(context,selected,true);startCaptions(selected);
  }
  function bind(context,selected,playing){
    const {root,state}=context,owned=ownedSet(state),host=root.querySelector("#labProjectionHost");
    root.querySelector("#labBack").onclick=context.onExit;
    root.querySelector("#labGemWorkshop").onclick=context.onOpenStorage;
    root.querySelectorAll("[data-lab-module]").forEach(button=>button.onclick=()=>{const module=MODULES.find(item=>item.id===button.dataset.labModule);if(!unlocked(module,owned))return notice(`${module.title} is locked. Exchange Knowledge Gems for its research device in Storage.`);state.science.labSelected=module.id;context.save();captionIndex=0;host.innerHTML=projection(module,true);bindProjection(context,module,true);startCaptions(module);host.scrollIntoView({behavior:"smooth",block:"center"})});
    root.querySelectorAll("[data-open-core]").forEach(button=>button.onclick=()=>root.querySelector('[data-lab-module="microscope"]')?.click());
    const synthesis=root.querySelector("#labSynthesis");if(synthesis&&!synthesis.disabled)synthesis.onclick=()=>openSynthesis(context);
    bindProjection(context,selected,playing);
  }
  function bindProjection(context,module,playing){const root=context.root,host=root.querySelector("#labProjectionHost"),play=root.querySelector("#labPlayPause"),replay=root.querySelector("#labReplay");if(play)play.onclick=()=>{const panel=host.querySelector(".lab-projection"),paused=panel.classList.toggle("paused");panel.classList.toggle("playing",!paused);play.textContent=paused?"▶ Play":"Ⅱ Pause";if(paused)clearInterval(clipTimer);else startCaptions(module)};if(replay)replay.onclick=()=>{captionIndex=0;host.innerHTML=projection(module,true);bindProjection(context,module,true);startCaptions(module)}}
  function startCaptions(module){clearInterval(clipTimer);clipTimer=setInterval(()=>{if(!active)return;captionIndex=(captionIndex+1)%module.captions.length;const caption=active.root.querySelector("#labClipCaption");if(caption)caption.textContent=module.captions[captionIndex]},4000)}
  function notice(message){if(!active)return;const node=active.root.querySelector("#labNotice");node.textContent=message;node.hidden=false;clearTimeout(notice.timer);notice.timer=setTimeout(()=>{if(node)node.hidden=true},3500)}
  function openSynthesis(context){const layer=context.root.querySelector("#labModal");layer.hidden=false;layer.innerHTML=`<article><button aria-label="Close synthesis planner">×</button><p>SCIENCE LAB · SAFE RESEARCH PLANNER</p><h2>Trait synthesis preview</h2><div class="synthesis-flow"><span><b>1</b>Choose a studied seed or specimen card</span><i>→</i><span><b>2</b>Compare inherited traits and habitat needs</span><i>→</i><span><b>3</b>Spend a Knowledge Gem only after the recipe is approved</span></div><aside><strong>Safety rule</strong><p>This prototype does not consume, delete or create organisms yet. It teaches the reasoning path before the full synthesis system is added.</p></aside><button class="synthesis-done">Record reviewed</button></article>`;const close=()=>{layer.hidden=true;layer.innerHTML=""};layer.querySelector('[aria-label="Close synthesis planner"]').onclick=close;layer.querySelector(".synthesis-done").onclick=close;layer.onclick=event=>{if(event.target===layer)close()}}
  function destroy(){clearInterval(clipTimer);clipTimer=0;active=null}
  function unlockCockpitEntrance(){const button=document.getElementById("cockpitLab");if(!button||button.dataset.labOpen==="true")return;button.dataset.labOpen="true";button.classList.remove("locked");let installed=0;try{const saved=JSON.parse(localStorage.getItem("international-math-adventure-v1")||"null");installed=MODULES.filter(module=>module.item&&(saved?.gemWorkshop?.owned||[]).includes(module.item)).length}catch{}const note=button.querySelector("small");if(note)note.textContent=`Microscope open · research devices ${installed}/6`;button.onclick=()=>document.dispatchEvent(new CustomEvent("open-science-lab"))}
  const entranceObserver=new MutationObserver(unlockCockpitEntrance);entranceObserver.observe(document.documentElement,{childList:true,subtree:true});unlockCockpitEntrance();
  window.ScienceLabRoom={mount:render,destroy,modules:MODULES};
})();
